base.css:
.op-toast {
  position: fixed;
  z-index: 50;
  left: 50%;
  bottom: 82px;
  max-width: calc(100vw - 32px);
  transform: translate(-50%, 16px);
  border-radius: 999px;
  padding: 10px 14px;
  background: #111827;
  color: #fff;
  font-size: 12px;
  font-weight: 700;
  opacity: 0;
  pointer-events: none;
  transition: .2s ease;
}
.op-toast.show { opacity: 1; transform: translate(-50%, 0); }

